"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Slot } from "../lib/slot";
import { useControllableState } from "../lib/hooks";

export interface ToggleProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange"> {
  pressed?: boolean;
  defaultPressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
  size?: "sm" | "md" | "lg";
  /** "ghost" is doorzichtig tot je hem indrukt, "outline" heeft altijd een rand. */
  variant?: "ghost" | "outline";
  icon?: React.ReactNode;
  asChild?: boolean;
}

/**
 * Toggle — knop die ingedrukt blijft staan, zoals vet of cursief in een
 * werkbalk. Voor aan/uit-instellingen gebruik je Switch.
 */
export const Toggle = React.forwardRef<HTMLButtonElement, ToggleProps>(function Toggle(
  {
    pressed,
    defaultPressed = false,
    onPressedChange,
    size = "md",
    variant = "ghost",
    icon,
    asChild,
    className,
    children,
    onClick,
    ...rest
  },
  ref
) {
  const [aan, setAan] = useControllableState<boolean>({
    value: pressed,
    defaultValue: defaultPressed,
    onChange: onPressedChange,
  });
  const Comp = (asChild ? Slot : "button") as React.ElementType;

  return (
    <Comp
      ref={ref}
      type={asChild ? undefined : "button"}
      aria-pressed={aan}
      data-state={aan ? "on" : "off"}
      className={cn(
        "pxui-toggle",
        `pxui-toggle-${size}`,
        `pxui-toggle-${variant}`,
        !children && "pxui-toggle-icon-only",
        className
      )}
      onClick={(event: React.MouseEvent<HTMLButtonElement>) => {
        onClick?.(event);
        setAan(!aan);
      }}
      {...rest}
    >
      {icon && <span className="pxui-toggle-icon">{icon}</span>}
      {children}
    </Comp>
  );
});

/* ------------------------------------------------------------------ */
/* ToggleGroup                                                         */
/* ------------------------------------------------------------------ */
interface ToggleGroupContextValue {
  waarden: string[];
  wissel: (value: string) => void;
  size: "sm" | "md" | "lg";
  variant: "ghost" | "outline";
  disabled?: boolean;
}

const ToggleGroupContext = React.createContext<ToggleGroupContextValue | null>(null);

export interface ToggleGroupProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> {
  /** "single" laat één keuze toe, "multiple" meerdere. */
  type?: "single" | "multiple";
  value?: string | string[];
  defaultValue?: string | string[];
  onValueChange?: (value: string & string[]) => void;
  size?: "sm" | "md" | "lg";
  variant?: "ghost" | "outline";
  disabled?: boolean;
  /** Knoppen aan elkaar geplakt in plaats van los. */
  joined?: boolean;
}

/** ToggleGroup — rij toggles die samen één keuze of een set keuzes vormen. */
export const ToggleGroup = React.forwardRef<HTMLDivElement, ToggleGroupProps>(function ToggleGroup(
  {
    type = "single",
    value,
    defaultValue,
    onValueChange,
    size = "md",
    variant = "ghost",
    disabled,
    joined,
    className,
    children,
    ...rest
  },
  ref
) {
  const naarLijst = (waarde: string | string[] | undefined): string[] =>
    waarde === undefined ? [] : Array.isArray(waarde) ? waarde : [waarde];

  const [waarden, setWaarden] = useControllableState<string[]>({
    value: value === undefined ? undefined : naarLijst(value),
    defaultValue: naarLijst(defaultValue),
    onChange: (volgende) => onValueChange?.((type === "single" ? (volgende[0] ?? "") : volgende) as string & string[]),
  });

  const wissel = (keuze: string) => {
    if (type === "single") {
      setWaarden(waarden.includes(keuze) ? [] : [keuze]);
      return;
    }
    setWaarden(waarden.includes(keuze) ? waarden.filter((w) => w !== keuze) : [...waarden, keuze]);
  };

  return (
    <ToggleGroupContext.Provider value={{ waarden, wissel, size, variant, disabled }}>
      <div
        ref={ref}
        role="group"
        className={cn("pxui-toggle-group", joined && "pxui-toggle-group-joined", className)}
        {...rest}
      >
        {children}
      </div>
    </ToggleGroupContext.Provider>
  );
});

export interface ToggleGroupItemProps extends Omit<ToggleProps, "pressed" | "defaultPressed" | "onPressedChange"> {
  value: string;
}

export const ToggleGroupItem = React.forwardRef<HTMLButtonElement, ToggleGroupItemProps>(
  function ToggleGroupItem({ value, size, variant, disabled, ...rest }, ref) {
    const groep = React.useContext(ToggleGroupContext);
    if (!groep) throw new Error("<ToggleGroupItem> moet binnen <ToggleGroup> staan.");

    return (
      <Toggle
        ref={ref}
        pressed={groep.waarden.includes(value)}
        onPressedChange={() => groep.wissel(value)}
        size={size ?? groep.size}
        variant={variant ?? groep.variant}
        disabled={disabled ?? groep.disabled}
        {...rest}
      />
    );
  }
);

/* ============================ Toggle ============================ */
.pxui-toggle {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  height: calc(36px * var(--density)); padding: 0 12px;
  border: 1px solid transparent; border-radius: var(--r-sm);
  background: transparent; color: var(--text-2);
  font: inherit; font-size: 13.5px; font-weight: 600; white-space: nowrap;
  cursor: pointer;
  transition: background var(--dur-fast) var(--ease), color var(--dur-fast) var(--ease),
    border-color var(--dur-fast) var(--ease);
}
.pxui-toggle:hover:not(:disabled) { background: var(--surface-3); color: var(--text); }
.pxui-toggle:focus-visible { outline: none; box-shadow: var(--ring); }
.pxui-toggle:disabled { opacity: .45; cursor: not-allowed; }

.pxui-toggle[data-state="on"] {
  background: var(--accent-tint); color: var(--accent); border-color: var(--accent-border);
}
.pxui-toggle[data-state="on"]:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent-tint) 72%, var(--accent));
}

.pxui-toggle-outline { border-color: var(--border); background: var(--surface); }
.pxui-toggle-outline:hover:not(:disabled) { background: var(--surface-2); }

.pxui-toggle-sm { height: calc(30px * var(--density)); padding: 0 9px; font-size: 12.5px; }
.pxui-toggle-lg { height: calc(42px * var(--density)); padding: 0 16px; font-size: 14.5px; }

.pxui-toggle-icon-only { padding: 0; width: calc(36px * var(--density)); }
.pxui-toggle-sm.pxui-toggle-icon-only { width: calc(30px * var(--density)); }
.pxui-toggle-lg.pxui-toggle-icon-only { width: calc(42px * var(--density)); }

.pxui-toggle-icon { display: inline-flex; }
.pxui-toggle-icon svg { width: 16px; height: 16px; }

/* ---------- ToggleGroup ---------- */
.pxui-toggle-group { display: inline-flex; align-items: center; gap: 4px; flex-wrap: wrap; }

.pxui-toggle-group-joined { gap: 0; }
.pxui-toggle-group-joined .pxui-toggle {
  border-color: var(--border); background: var(--surface); border-radius: 0;
}
.pxui-toggle-group-joined .pxui-toggle + .pxui-toggle { margin-left: -1px; }
.pxui-toggle-group-joined .pxui-toggle:first-child {
  border-radius: var(--r-sm) 0 0 var(--r-sm);
}
.pxui-toggle-group-joined .pxui-toggle:last-child {
  border-radius: 0 var(--r-sm) var(--r-sm) 0;
}
.pxui-toggle-group-joined .pxui-toggle[data-state="on"] { position: relative; z-index: 1; }
